const webhookItem = $('Webhook1').first()?.json ?? {};
const payload = webhookItem.body ?? webhookItem;
const event = String(payload?.event || '').toLowerCase();

if (event !== 'seeker_resume_uploaded') {
  return [];
}

const seekerEmail = String(payload.email || '').trim();
if (!seekerEmail) {
  throw new Error('Missing seeker email in payload');
}

const seekerName = String(payload.name || 'Jobseeker').trim();
const resumeText = String(payload.resume_text || '').toLowerCase();
const seekerEducation = String(payload.educational_attainment || '').toLowerCase();

let seekerSkills = payload.parsed_skill ?? [];
if (typeof seekerSkills === 'string') {
  try {
    seekerSkills = JSON.parse(seekerSkills);
  } catch {
    seekerSkills = [seekerSkills];
  }
}
if (!Array.isArray(seekerSkills) && typeof seekerSkills === 'object' && seekerSkills !== null) {
  seekerSkills = Object.values(seekerSkills);
}
seekerSkills = seekerSkills.map((s) => String(s).toLowerCase().trim()).filter(Boolean);

const jobs = $input.all().map((item) => item.json);
const scored = [];

const eduMap = {
  doctorate: ['phd', 'doctorate', 'doctor of'],
  masters: ['master', 'ms', 'ma', 'mba'],
  bachelors: ['bachelor', 'bs', 'ba', 'college', 'degree'],
  vocational: ['vocational', 'tesda', 'certificate'],
  highschool: ['high school', 'secondary']
};

for (const job of jobs) {
  const title = String(job.title || '');
  const company = String(job.company || '');
  const location = String(job.location || '');
  const description = String(job.description || '').toLowerCase();
  const requiredEducation = String(job.educational_attainment_required || '').toLowerCase();

  let requiredSkills = job.required_skills ?? [];
  if (typeof requiredSkills === 'string') {
    try {
      requiredSkills = JSON.parse(requiredSkills);
    } catch {
      requiredSkills = [requiredSkills];
    }
  }
  if (!Array.isArray(requiredSkills) && typeof requiredSkills === 'object' && requiredSkills !== null) {
    requiredSkills = Object.values(requiredSkills);
  }
  requiredSkills = requiredSkills.map((s) => String(s).toLowerCase().trim()).filter(Boolean);

  let score = 0;
  const reasons = [];

  let skillHits = 0;
  for (const skill of requiredSkills) {
    if (seekerSkills.includes(skill) || resumeText.includes(skill)) {
      skillHits++;
    }
  }
  if (requiredSkills.length > 0) {
    const skillScore = (skillHits / requiredSkills.length) * 60;
    score += skillScore;
    if (skillHits > 0) reasons.push(`${skillHits}/${requiredSkills.length} required skills matched`);
  }

  const titleKeywords = title.toLowerCase().split(/\s+/).filter((w) => w.length > 3);
  const titleHits = titleKeywords.filter((k) => resumeText.includes(k)).length;
  if (titleKeywords.length > 0) {
    const titleScore = (titleHits / titleKeywords.length) * 25;
    score += titleScore;
    if (titleHits > 0) reasons.push(`title alignment (${titleHits} keyword hit/s)`);
  }

  if (requiredEducation && requiredEducation !== 'any') {
    const eduMatched = seekerEducation.includes(requiredEducation) || resumeText.includes(requiredEducation) || Object.values(eduMap).some((keys) => keys.some((k) => requiredEducation.includes(k) && (seekerEducation.includes(k) || resumeText.includes(k))));
    if (eduMatched) {
      score += 15;
      reasons.push('education aligned');
    }
  } else {
    score += 10;
  }

  const finalScore = Math.round(Math.min(score, 100));
  if (finalScore > 0) {
    scored.push({
      job_id: job.id,
      title,
      company,
      location,
      score: finalScore,
      reasons: reasons.join(' | ') || 'General profile fit'
    });
  }
}

scored.sort((a, b) => b.score - a.score);
const top = scored.slice(0, 5);

return [{
  json: {
    event: 'seeker_resume_uploaded',
    to_email: seekerEmail,
    seeker_name: seekerName,
    recommendations: top
  }
}];
